Method.Source:
/// <summary>
/// AVA
/// </summary>
/// <param name = "sender">FormDataSource</param>
/// <param name = "e">FormDataSourceEventArgs</param>
[   SuppressBPWarning('BPParameterNotUsed', 'False positive'),
    FormDataSourceEventHandler(formDataSourceStr(ProdTableOverview, ProdTable), FormDataSourceEventType::Activated)]
public static void ProdTable_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
{
    FormRun                 formRun = sender.formRun();
    ProdTable               prodTable = sender.cursor();      

    if (prodTable.ProdStatus == ProdStatus::Released || prodTable.ProdStatus == ProdStatus::StartedUp || prodTable.ProdStatus == ProdStatus::ReportedFinished || prodTable.ProdStatus == ProdStatus::Completed)
    {
        formRun.design().controlName(formControlStr(ProdTableOverview, AVACreateTraverseTrans)).enabled(true);
    }
    else
    {
        formRun.design().controlName(formControlStr(ProdTableOverview, AVACreateTraverseTrans)).enabled(false);
    }

}
